package run.ikaros.sharing; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/shares") public class ShareController{private final ShareService service;public ShareController(ShareService s){service=s;}@PostMapping public Mono<ShareView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateShareRequest r){return service.create(o,r);}@GetMapping public Flux<ShareView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.list(o);}@PostMapping("/{shareId}/actions/revoke")public Mono<ShareView> revoke(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID shareId){return service.revoke(o,shareId);}@PostMapping("/redeem")public Mono<ShareView> redeem(@RequestParam String token){return service.redeem(token);}}
